 * @param status           簇状态：OPEN 未结 / CLOSED 已完成联合裁决
 * @param operator         建簇审核员标识
 * @param closedAtUtc      簇关闭时刻（UTC）；OPEN 时为 null
 */
public record BundleRecord(
