        List<String> consistentFields,
        String status,
        String operator,
        Instant closedAtUtc) {

    public static final String OPEN = "OPEN";
    public static final String CLOSED = "CLOSED";

    public boolean open() {
        return OPEN.equals(status);
    }
}

