/**
 * 挂接未结簇；该观测已在其他未结簇时拒绝（不允许重复加入）。
 */
private void attachOrReject(String observationId, String bundleKey) {
    ObservationSnapshot existing = observationRepository.findCurrentForUpdate(observationId)
            .orElseThrow(() -> ApiException.notFound("observation not found: " + observationId));
    if (existing.openBundleKey() == null) {
        return;
    }
    if (Objects.equals(existing.openBundleKey(), bundleKey)) {
        throw ApiException.conflict(
                "observation already attached to this bundle: " + observationId, existing.version());
    }
    throw ApiException.conflict(
            "observation already belongs to another open bundle: " + observationId, existing.version());
}

