    @Test
    void incompleteOrChangedArbitrationRollsBackEverything() throws Exception {
        createObservation("req-1", "obs-a", "survey-1", "站点A", "1.0", "备注");
        merge("req-2", "obs-a", 1, "站点B", "2.0", "备注");
